import csv,json,re,sys
sys.path.insert(0,'/workspace/japanese')
src=open('/workspace/japanese/mk.py').read()
ns={}
for line in src.splitlines():
    if line.startswith(('ru=','U=','vg=')): exec(line,ns)
RU=ns['ru'];VG=ns['vg']
T="""университет, колледж|старшая школа|учащийся, студент|студент (вуза)|иностранный студент|учитель, преподаватель|студент ...-го курса|первокурсник, ученик 1-го класса/курса|специальность (в вузе)|я|друг, подруга|господин/госпожа ... (вежливый суффикс)|... (национальность, -ец/-ка)|японец, японцы|сейчас|до полудня (a.m.)|после полудня (p.m.)|... час(ов)|час (1:00)|половина (полчаса)|половина третьего (2:30)|Япония|США, Америка|... язык|японский язык|... лет (возраст)|телефон|номер ...|номер|имя|что|э-э... (вежливое начало)|да|Да, верно.|Вот как.; Правда?|Великобритания, Англия|Австралия|Корея|Канада|Китай|Индия|Египет|Филиппины|азиатские исследования, востоковедение|экономика|инженерное дело, техника|международные отношения|компьютер|политика, политология|биология|бизнес|литература|история|врач|офисный служащий|медсестра|старшеклассник|домохозяйка|аспирант, магистрант|юрист, адвокат|мама, мать|папа, отец|старшая сестра|старший брат|младшая сестра|младший брат|это (около меня)|это/то (около собеседника)|вон то (далеко от обоих)|который (из них)|этот ...|тот ... (около собеседника)|вон тот ...|какой ..., который ...|здесь|там (около собеседника)|вон там|где|кто|вкусный|рыба|тонкацу (свиная отбивная)|мясо|меню|овощи|зонт|сумка, портфель|обувь, туфли|кошелёк|джинсы|велосипед|газета|смартфон, мобильный|футболка|часы|тетрадь|ручка|шапка, шляпа, кепка|книга|банк|круглосуточный магазин (комбини)|туалет|библиотека|почта (почтовое отделение)|английский язык|сколько (стоит)|... иен|дорогой; высокий|Добро пожаловать! (в магазине)|..., пожалуйста (прошу)|Дайте, пожалуйста, ...|Тогда...; Ну, раз так...|Пожалуйста (предлагая); Вот, держите.|Спасибо.|1 час|2 часа|3 часа|4 часа|5 часов|6 часов|7 часов|8 часов|9 часов|10 часов|11 часов|12 часов|1 минута|2 минуты|3 минуты|4 минуты|5 минут|6 минут|7 минут|8 минут|9 минут|10 минут|20 минут|30 минут""".split('|')
MINR={'いっぷん':'ippun','にふん':'nifun','さんぷん':'sanpun','よんぷん':'yonpun','ごふん':'gofun','ろっぷん':'roppun','ななふん':'nanafun','はっぷん／はちふん':'happun/hachifun','きゅうふん':'kyuufun','じゅっぷん（じっぷん）':'juppun/jippun','にじゅっぷん':'nijuppun','さんじゅっぷん':'sanjuppun'}
LES=[('словарик1','Урок 1'),('словарик2','Урок 2'),('словарик3','Урок 3'),('часы','Часы и минуты')]
out=[];i=0
for r in csv.DictReader(open('/workspace/japanese/vocab.csv')):
    les=next(n for k,n in LES if k in r['source']); j=r['japanese']; rd=r['reading'] or MINR.get(j,'')
    if les=='Урок 3':
        ru=RU[j]; w={'jp':j,'reading':rd if rd!=j else '','ru':ru,'lesson':les}
        if j in VG: w['verbInfo']=f"{VG[j][0]}; ます: {VG[j][1]}"
    else:
        w={'jp':j,'reading':rd,'ru':T[i],'lesson':les}; i+=1
    out.append(w)
assert i==len(T),(i,len(T))
json.dump({'lessons':[n for _,n in LES],'words':out},open('words.json','w'),ensure_ascii=False,indent=1)
from collections import Counter;print(len(out),Counter(w['lesson'] for w in out))
